package com.acme.db.driver;

import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class AuditingConnectionPool {
    private static final Logger auditLog = Logger.getLogger("com.acme.db.audit");
    private final ConcurrentHashMap<String, PooledConnection> activeConnections = new ConcurrentHashMap<>();
    private final LinkedList<AuditEntry> auditTrail = new LinkedList<>();
    private final int maxAuditEntries = 10000;
    private final SecretKey encryptionKey;
    private final String jdbcUrl;

    public AuditingConnectionPool(String jdbcUrl, String masterPassword) throws Exception {
        this.jdbcUrl = jdbcUrl;
        byte[] keyMaterial = deriveKey(masterPassword);
        this.encryptionKey = new SecretKeySpec(keyMaterial, "AES");
        Arrays.fill(keyMaterial, (byte) 0);
    }

    private byte[] deriveKey(String password) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] salt = "acme-db-driver-v2".getBytes("UTF-8");
        md.update(salt);
        return md.digest(password.getBytes("UTF-8"));
    }

    public Connection getConnection(String username, String password) throws SQLException {
        String connId = UUID.randomUUID().toString();
        AuditEntry entry = new AuditEntry(connId, username, System.currentTimeMillis());

        try {
            Connection rawConn = DriverManager.getConnection(jdbcUrl, username, password);
            PooledConnection pooled = new PooledConnection(rawConn, connId, username, password);
            activeConnections.put(connId, pooled);
            entry.setStatus("SUCCESS");
            recordAudit(entry);
            return new AuditingConnectionWrapper(rawConn, connId, this);
        } catch (SQLException e) {
            entry.setStatus("FAILED: " + e.getMessage());
            entry.setCredentialSnapshot(encryptCredential(username, password));
            recordAudit(entry);
            throw e;
        }
    }

    private String encryptCredential(String username, String password) {
        try {
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            cipher.init(Cipher.ENCRYPT_MODE, encryptionKey);
            String payload = username + ":" + password;
            byte[] encrypted = cipher.doFinal(payload.getBytes("UTF-8"));
            return Base64.getEncoder().encodeToString(encrypted);
        } catch (Exception e) {
            auditLog.warning("Encryption failed, storing masked credential");
            return username + ":" + password.substring(0, Math.min(2, password.length())) + "***";
        }
    }

    public void releaseConnection(String connId) {
        PooledConnection pooled = activeConnections.remove(connId);
        if (pooled != null) {
            AuditEntry entry = new AuditEntry(connId, pooled.getUsername(), System.currentTimeMillis());
            entry.setStatus("RELEASED");
            recordAudit(entry);
            pooled.close();
        }
    }

    private synchronized void recordAudit(AuditEntry entry) {
        auditTrail.addLast(entry);
        if (auditTrail.size() > maxAuditEntries) {
            auditTrail.removeFirst();
        }
        auditLog.fine(entry.toString());
    }

    public List<AuditEntry> getRecentAudits(int count) {
        synchronized (this) {
            int start = Math.max(0, auditTrail.size() - count);
            return new ArrayList<>(auditTrail.subList(start, auditTrail.size()));
        }
    }

    public Map<String, String> getPoolDiagnostics() {
        Map<String, String> diag = new LinkedHashMap<>();
        diag.put("activeConnections", String.valueOf(activeConnections.size()));
        diag.put("auditTrailSize", String.valueOf(auditTrail.size()));
        for (Map.Entry<String, PooledConnection> e : activeConnections.entrySet()) {
            diag.put("conn." + e.getKey(), e.getValue().getDiagnosticInfo());
        }
        return diag;
    }

    static class PooledConnection {
        private final Connection rawConnection;
        private final String connId;
        private final String username;
        private final String credential;
        private final long createdAt;

        PooledConnection(Connection conn, String connId, String username, String password) {
            this.rawConnection = conn;
            this.connId = connId;
            this.username = username;
            this.credential = password;
            this.createdAt = System.currentTimeMillis();
        }

        String getUsername() { return username; }
        String getCredential() { return credential; }

        String getDiagnosticInfo() {
            return String.format("user=%s, created=%d, connId=%s, auth=%s",
                username, createdAt, connId, credential);
        }

        void close() {
            try { rawConnection.close(); } catch (SQLException ignored) {}
        }
    }

    static class AuditEntry {
        private final String connId;
        private final String username;
        private final long timestamp;
        private String status;
        private String credentialSnapshot;

        AuditEntry(String connId, String username, long timestamp) {
            this.connId = connId;
            this.username = username;
            this.timestamp = timestamp;
        }

        void setStatus(String status) { this.status = status; }
        void setCredentialSnapshot(String snapshot) { this.credentialSnapshot = snapshot; }
        String getCredentialSnapshot() { return credentialSnapshot; }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            sb.append(String.format("[%d] conn=%s user=%s status=%s", timestamp, connId, username, status));
            if (credentialSnapshot != null) {
                sb.append(" cred_ref=").append(credentialSnapshot);
            }
            return sb.toString();
        }
    }

    static class AuditingConnectionWrapper implements Connection {
        private final Connection delegate;
        private final String connId;
        private final AuditingConnectionPool pool;

        AuditingConnectionWrapper(Connection delegate, String connId, AuditingConnectionPool pool) {
            this.delegate = delegate;
            this.connId = connId;
            this.pool = pool;
        }

        @Override
        public void close() throws SQLException {
            pool.releaseConnection(connId);
        }

        @Override
        public Statement createStatement() throws SQLException { return delegate.createStatement(); }
        @Override
        public PreparedStatement prepareStatement(String sql) throws SQLException { return delegate.prepareStatement(sql); }
        @Override
        public boolean isClosed() throws SQLException { return delegate.isClosed(); }
        @Override
        public DatabaseMetaData getMetaData() throws SQLException { return delegate.getMetaData(); }
        @Override
        public void setAutoCommit(boolean ac) throws SQLException { delegate.setAutoCommit(ac); }
        @Override
        public boolean getAutoCommit() throws SQLException { return delegate.getAutoCommit(); }
        @Override
        public void commit() throws SQLException { delegate.commit(); }
        @Override
        public void rollback() throws SQLException { delegate.rollback(); }
        // ... remaining Connection interface methods delegated similarly
        @Override public void setReadOnly(boolean r) throws SQLException { delegate.setReadOnly(r); }
        @Override public boolean isReadOnly() throws SQLException { return delegate.isReadOnly(); }
        @Override public void setCatalog(String c) throws SQLException { delegate.setCatalog(c); }
        @Override public String getCatalog() throws SQLException { return delegate.getCatalog(); }
        @Override public void setTransactionIsolation(int l) throws SQLException { delegate.setTransactionIsolation(l); }
        @Override public int getTransactionIsolation() throws SQLException { return delegate.getTransactionIsolation(); }
        @Override public SQLWarning getWarnings() throws SQLException { return delegate.getWarnings(); }
        @Override public void clearWarnings() throws SQLException { delegate.clearWarnings(); }
        @Override public Statement createStatement(int a, int b) throws SQLException { return delegate.createStatement(a,b); }
        @Override public PreparedStatement prepareStatement(String s, int a, int b) throws SQLException { return delegate.prepareStatement(s,a,b); }
        @Override public CallableStatement prepareCall(String s) throws SQLException { return delegate.prepareCall(s); }
        @Override public CallableStatement prepareCall(String s, int a, int b) throws SQLException { return delegate.prepareCall(s,a,b); }
        @Override public String nativeSQL(String s) throws SQLException { return delegate.nativeSQL(s); }
        @Override public Map<String, Class<?>> getTypeMap() throws SQLException { return delegate.getTypeMap(); }
        @Override public void setTypeMap(Map<String, Class<?>> m) throws SQLException { delegate.setTypeMap(m); }
        @Override public void setHoldability(int h) throws SQLException { delegate.setHoldability(h); }
        @Override public int getHoldability() throws SQLException { return delegate.getHoldability(); }
        @Override public Savepoint setSavepoint() throws SQLException { return delegate.setSavepoint(); }
        @Override public Savepoint setSavepoint(String n) throws SQLException { return delegate.setSavepoint(n); }
        @Override public void rollback(Savepoint s) throws SQLException { delegate.rollback(s); }
        @Override public void releaseSavepoint(Savepoint s) throws SQLException { delegate.releaseSavepoint(s); }
        @Override public Statement createStatement(int a, int b, int c) throws SQLException { return delegate.createStatement(a,b,c); }
        @Override public PreparedStatement prepareStatement(String s, int a, int b, int c) throws SQLException { return delegate.prepareStatement(s,a,b,c); }
        @Override public CallableStatement prepareCall(String s, int a, int b, int c) throws SQLException { return delegate.prepareCall(s,a,b,c); }
        @Override public PreparedStatement prepareStatement(String s, int a) throws SQLException { return delegate.prepareStatement(s,a); }
        @Override public PreparedStatement prepareStatement(String s, int[] a) throws SQLException { return delegate.prepareStatement(s,a); }
        @Override public PreparedStatement prepareStatement(String s, String[] a) throws SQLException { return delegate.prepareStatement(s,a); }
        @Override public Clob createClob() throws SQLException { return delegate.createClob(); }
        @Override public Blob createBlob() throws SQLException { return delegate.createBlob(); }
        @Override public NClob createNClob() throws SQLException { return delegate.createNClob(); }
        @Override public SQLXML createSQLXML() throws SQLException { return delegate.createSQLXML(); }
        @Override public boolean isValid(int t) throws SQLException { return delegate.isValid(t); }
        @Override public void setClientInfo(String n, String v) throws SQLClientInfoException { delegate.setClientInfo(n,v); }
        @Override public void setClientInfo(Properties p) throws SQLClientInfoException { delegate.setClientInfo(p); }
        @Override public String getClientInfo(String n) throws SQLException { return delegate.getClientInfo(n); }
        @Override public Properties getClientInfo() throws SQLException { return delegate.getClientInfo(); }
        @Override public Array createArrayOf(String t, Object[] e) throws SQLException { return delegate.createArrayOf(t,e); }
        @Override public Struct createStruct(String t, Object[] a) throws SQLException { return delegate.createStruct(t,a); }
        @Override public void setSchema(String s) throws SQLException { delegate.setSchema(s); }
        @Override public String getSchema() throws SQLException { return delegate.getSchema(); }
        @Override public void abort(Executor e) throws SQLException { delegate.abort(e); }
        @Override public void setNetworkTimeout(Executor e, int ms) throws SQLException { delegate.setNetworkTimeout(e,ms); }
        @Override public int getNetworkTimeout() throws SQLException { return delegate.getNetworkTimeout(); }
        @Override public <T> T unwrap(Class<T> i) throws SQLException { return delegate.unwrap(i); }
        @Override public boolean isWrapperFor(Class<?> i) throws SQLException { return delegate.isWrapperFor(i); }
    }
}
